import java.util.*;
import java.io.*;

public class Main {
    static final int INF = 0x3f3f3f3f;
    static final long MOD = 1000000007L;
    static final long INV = 570000004L;
    static final double EPSILON = 0.00001;
    static final int MN = 22;
    static long[][] p = new long[MN][MN];
    static List<int[]> permsA = new ArrayList<>();
    static List<int[]> permsB = new ArrayList<>();
    static long[] bmA = new long[1 << 18];
    static long[] bmB = new long[1 << 18];
    static long[] f = new long[1 << 20];

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int t = 0;
        int[] aah = {0, 1, 2, 3, 4, 5};
        do {
            if (aah[0] < aah[1] && aah[1] < aah[2] && aah[3] < aah[4] && aah[4] < aah[5]) {
                permsA.add(new int[]{aah[0], aah[1], aah[2]});
                permsB.add(new int[]{aah[3], aah[4], aah[5]});
            }
        } while (nextPermutation(aah));

        int n = sc.nextInt();
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                p[i][j] = sc.nextLong();
                p[i][j] = (p[i][j] * INV) % MOD;
            }
        }
        for (int i = 0; i < 6; ++i) {
            for (int j = n; j < 6; ++j) {
                if (i == j) p[i][j] = 1;
                else { p[i][j] = 0; p[j][i] = 0; }
            }
        }
        n = 6;

        for (int mask = 0; mask < (1 << 18); ++mask) {
            long prob1 = 1, prob2 = 1;
            int bm1 = 0, bm2 = 0;
            for (int j = 0; j < 6; ++j) {
                for (int k = 0; k < 3; ++k) {
                    int res = j * 3 + k;
                    if (((mask >> res) & 1) != 0) {
                        prob1 = (prob1 * p[j][k]) % MOD;
                        prob2 = (prob2 * p[j][k + 3]) % MOD;
                    } else {
                        prob1 = (prob1 * (1 + MOD - p[j][k])) % MOD;
                        prob2 = (prob2 * (1 + MOD - p[j][k + 3])) % MOD;
                    }
                }
            }
            for (int ot = 0; ot < 20; ++ot) {
                int[] ord = {0, 1, 2};
                boolean ok = false;
                do {
                    boolean ok2 = true;
                    for (int j = 0; j < 3; ++j) {
                        int val = permsA.get(ot)[ord[j]];
                        int loc = val * 3 + j;
                        if (((mask >> loc) & 1) == 0) {
                            ok2 = false;
                            break;
                        }
                    }
                    if (ok2) {
                        ok = true;
                        break;
                    }
                } while (nextPermutation(ord));
                if (ok) bm1 ^= (1 << ot);
            }
            for (int ot = 0; ot < 20; ++ot) {
                int[] ord = {0, 1, 2};
                boolean ok = false;
                do {
                    boolean ok2 = true;
                    for (int j = 0; j < 3; ++j) {
                        int val = permsB.get(ot)[ord[j]];
                        int loc = val * 3 + j;
                        if (((mask >> loc) & 1) == 0) {
                            ok2 = false;
                            break;
                        }
                    }
                    if (ok2) {
                        ok = true;
                        break;
                    }
                } while (nextPermutation(ord));
                if (ok) bm2 ^= (1 << ot);
            }
            bmA[bm1] = (bmA[bm1] + prob1) % MOD;
            bmB[bm2] = (bmB[bm2] + prob2) % MOD;
        }

        for (int i = 0; i < (1 << 20); ++i) {
            f[i] = bmA[i];
        }

        for (int i = 0; i < 20; ++i) {
            for (int mask = 0; mask < (1 << 20); ++mask) {
                if ((mask & (1 << i)) != 0) {
                    f[mask] = (f[mask] + f[mask ^ (1 << i)]) % MOD;
                }
            }
        }

        long sm = 0;
        int full_mask = (1 << 20) - 1;
        for (int i = 0; i < (1 << 20); ++i) {
            sm = (sm + bmB[i] * f[full_mask ^ i]) % MOD;
        }
        System.out.println((1 + MOD - sm) % MOD);
    }

    static boolean nextPermutation(int[] arr) {
        int i = arr.length - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) i--;
        if (i < 0) return false;
        int j = arr.length - 1;
        while (arr[j] <= arr[i]) j--;
        swap(arr, i, j);
        reverse(arr, i + 1, arr.length - 1);
        return true;
    }

    static void swap(int[] arr, int i, int j) {
        int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
    }

    static void reverse(int[] arr, int start, int end) {
        while (start < end) {
            swap(arr, start++, end--);
        }
    }
}
